import os,stat,shutil
from pathlib import Path
def clone_tree(source,destination):
 source=Path(source);destination=Path(destination);directories=[];files=[]
 if source.is_symlink() or not source.is_dir():raise ValueError('real directory required')
 for current,dirs,names in os.walk(source,followlinks=False):
  for name in dirs+names:
   path=Path(current)/name;info=path.lstat();relative=path.relative_to(source)
   if stat.S_ISDIR(info.st_mode):directories.append(relative)
   elif stat.S_ISREG(info.st_mode):files.append((relative,info))
   else:raise ValueError('only regular files and directories allowed')
 destination.mkdir();groups={}
 for relative in sorted(directories,key=lambda p:(len(p.parts),str(p))):(destination/relative).mkdir()
 for relative,info in files:
  target=destination/relative;key=(info.st_dev,info.st_ino)
  if key in groups:os.link(groups[key],target)
  else:shutil.copyfile(source/relative,target);groups[key]=target
```

